pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function testFuzz_property(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner != address(this));
        uint256 initialBalance = 1 ether;
        vm.deal(address(c), initialBalance);
        amount = bound(amount, 0, initialBalance);

        uint256 balanceBefore = address(c).balance;

        vm.prank(nonOwner);
        try c.sendTo(address(0xdead), amount) {
        } catch {
        }

        assertEq(address(c).balance, balanceBefore, "Balance must not change on non-owner call");
    }
}
